import json
ms={}
for l in open('Medication.ndjson'):
    m=json.loads(l)
    name=None
    for i in m.get('identifier',[]):
        if i['system'].endswith('medication-name'): name=i['value']
    ms[m['id']]=name or json.dumps(m.get('code'))
json.dump(ms,open('medmap.json','w'))
kw=['warfarin','coumadin','apixaban','eliquis','rivaroxaban','xarelto','dabigatran','pradaxa','edoxaban','savaysa','heparin','enoxaparin','lovenox','fondaparinux','argatroban','bivalirudin','dalteparin','citalopram','escitalopram','haloperidol','methadone','amiodarone','sotalol','dofetilide']
import collections
found=collections.defaultdict(set)
for i,n in ms.items():
    ln=(n or '').lower()
    for k in kw:
        if k in ln: found[k].add(n)
for k in kw:
    print(k, sorted(found[k]))
